'use server';
/**
 * @fileoverview A flow that finds tourist attractions in a given city using the Google Places API.
 */

import { ai } from '@/ai/genkit';
import { z } from 'genkit';
import { Client } from '@googlemaps/google-maps-services-js';

const AttractionSchema = z.object({
  name: z.string().describe('The name of the attraction.'),
  address: z.string().describe('The address of the attraction.'),
  rating: z.number().optional().describe('The user rating of the attraction (out of 5).'),
  userRatingsTotal: z.number().optional().describe('The total number of user ratings.'),
  priceLevel: z.number().optional().describe('The price level of the attraction (0-4).'),
  types: z.array(z.string()).optional().describe('An array of types for the attraction (e.g., "museum", "park").'),
  photoReference: z.string().optional().describe('A reference for a photo of the attraction.'),
});

const FindAttractionsInputSchema = z.object({
  city: z.string().describe('The city to search for attractions in (e.g., "Bengaluru").'),
  category: z.string().optional().describe('A category to filter attractions by (e.g., "museum", "park", "temple").'),
});

const FindAttractionsOutputSchema = z.object({
  attractions: z.array(AttractionSchema),
});

export type FindAttractionsInput = z.infer<typeof FindAttractionsInputSchema>;
export type FindAttractionsOutput = z.infer<typeof FindAttractionsOutputSchema>;

const mapsClient = new Client({});

const findAttractionsTool = ai.defineTool(
  {
    name: 'findAttractions',
    description: 'Finds tourist attractions in a given city.',
    inputSchema: FindAttractionsInputSchema,
    outputSchema: FindAttractionsOutputSchema,
  },
  async (input) => {
    if (!process.env.GOOGLE_MAPS_API_KEY) {
      throw new Error('Google Maps API key is missing. Please add it to your .env file.');
    }

    try {
      const query = `tourist attractions in ${input.city} ${input.category || ''}`;
      const response = await mapsClient.textSearch({
        params: {
          query: query,
          key: process.env.GOOGLE_MAPS_API_KEY,
        },
      });

      if (response.data.status !== 'OK' && response.data.status !== 'ZERO_RESULTS') {
        console.error('Google Places API Error:', response.data.error_message || response.data.status);
        throw new Error(`Google Places API Error: ${response.data.error_message || response.data.status}`);
      }

      const attractions = response.data.results.map(place => ({
        name: place.name || 'N/A',
        address: place.formatted_address || 'N/A',
        rating: place.rating,
        userRatingsTotal: place.user_ratings_total,
        priceLevel: place.price_level,
        types: place.types,
        photoReference: place.photos?.[0]?.photo_reference,
      }));

      return { attractions };
    } catch (error) {
      console.error('Error fetching attractions from Google Places API:', error);
      // Re-throw the error to be caught by the page component
      throw error;
    }
  }
);


const findAttractionsFlow = ai.defineFlow(
  {
    name: 'findAttractionsFlow',
    inputSchema: FindAttractionsInputSchema,
    outputSchema: FindAttractionsOutputSchema,
    system: "You are an expert travel agent. Your goal is to find tourist attractions for a user. Use the findAttractions tool.",
    tools: [findAttractionsTool],
  },
  async (input) => {
    
    // We are directly calling the tool here instead of letting the LLM decide.
    // This is because we *always* want to find attractions.
    const toolResult = await findAttractionsTool(input);

    return toolResult;
  }
);

export async function findAttractions(input: FindAttractionsInput): Promise<FindAttractionsOutput> {
  return findAttractionsFlow(input);
}
