import { getCityByName } from "@/lib/data";
import { notFound } from "next/navigation";
import Image from "next/image";
import { PlaceHolderImages } from "@/lib/placeholder-images";
import { AttractionsTabs } from "@/components/city/AttractionsTabs";
import { findAttractions } from "@/ai/flows/find-attractions";
import type { Attraction } from "@/lib/types";
import { AlertCircle } from "lucide-react";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";

type CityPageProps = {
  params: {
    cityName: string;
  };
};

export default async function CityPage({ params }: CityPageProps) {
  const city = getCityByName(params.cityName);

  if (!city) {
    notFound();
  }

  let attractions: Attraction[] = [];
  let error: string | null = null;

  try {
    const attractionsData = await findAttractions({ city: city.name });
    attractions = attractionsData.attractions.map((att, index) => ({
      id: att.name.toLowerCase().replace(/\s/g, '-') + index,
      name: att.name,
      description: `Located at ${att.address}. ${att.types ? 'Categories: ' + att.types.join(', ') : ''}`,
      images: att.photoReference ? [`https://maps.googleapis.com/maps/api/place/photo?maxwidth=400&photoreference=${att.photoReference}&key=${process.env.GOOGLE_MAPS_API_KEY}`] : ['placeholder-image'],
      category: att.types?.find(t => ['museum', 'waterfall', 'fort', 'park', 'temple'].includes(t)) as Attraction['category'] || 'Fort',
      latitude: 0, // Not provided by our simplified API tool
      longitude: 0, // Not provided by our simplified API tool
      reviews: att.rating ? [{
        id: `r-${index}`,
        author: 'Google User',
        rating: att.rating,
        comment: `Rated ${att.rating} out of 5 by ${att.userRatingsTotal || 'several'} users.`
      }] : [],
      priceLevel: att.priceLevel,
      address: att.address,
    }));
  } catch (e: any) {
    console.error(e);
    error = e.message || "An unknown error occurred while fetching attractions.";
  }


  const cityImage = PlaceHolderImages.find((img) => img.id === city.image);

  return (
    <div className="flex flex-col">
      <section className="relative h-[40vh] w-full flex items-end justify-start text-white p-8">
        {cityImage && (
          <Image
            src={cityImage.imageUrl}
            alt={cityImage.description}
            fill
            className="object-cover"
            priority
            data-ai-hint={cityImage.imageHint}
          />
        )}
        <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/40 to-transparent" />
        <div className="relative z-10">
          <h1 className="text-5xl md:text-6xl font-bold font-headline tracking-tight">
            {city.name}
          </h1>
          <p className="max-w-3xl text-lg text-neutral-200 mt-2">
            {city.description}
          </p>
        </div>
      </section>

      <section className="container mx-auto px-4 py-12">
        {error && (
          <Alert variant="destructive" className="mb-8">
            <AlertCircle className="h-4 w-4" />
            <AlertTitle>Error Loading Attractions from Google Maps</AlertTitle>
            <AlertDescription>
              Could not load attractions. This is likely due to an issue with the Google Maps API key configuration. Please ensure the <strong>Places API</strong> is enabled and that <strong>billing is active</strong> on your Google Cloud project.
              <p className="font-mono text-xs mt-2 p-2 bg-black/10 rounded">Details: {error}</p>
            </AlertDescription>
          </Alert>
        )}
        <AttractionsTabs attractions={attractions} />
      </section>
    </div>
  );
}
